async function ensureFreeAccountAppsWithDatabase(database, tenantId, ownerUserId) {
  const metadataPatchJson = JSON.stringify(FREE_ACCOUNT_METADATA_PATCH);
  for (const slug2 of FREE_ACCOUNT_APP_SLUGS) {
    const [mod] = await database.select().from(modules).where(eq7(modules.slug, slug2)).limit(1);
    if (!mod) {
      console.warn(`[free-apps] module '${slug2}' not found; skipping free-account grant`);
      continue;
    }
    const [existing] = await database.select().from(tenantModules).where(and7(
      eq7(tenantModules.tenantId, tenantId),
      eq7(tenantModules.moduleId, mod.id)
    )).limit(1);
    const migrateLegacyGrant = !existing || shouldUpgradeLegacyFreeAccountGrant(existing);
    if (!existing) {
      await database.insert(tenantModules).values({
        tenantId,
        moduleId: mod.id,
        status: "enabled",
        source: "included",
        allowAllMembers: true,
        metadata: NEW_FREE_ACCOUNT_GRANT_METADATA
      }).onConflictDoNothing({ target: [tenantModules.tenantId, tenantModules.moduleId] });
    } else if (migrateLegacyGrant) {
      await database.update(tenantModules).set({
        status: "enabled",
        source: "included",
        allowAllMembers: true,
        metadata: sql5`COALESCE(${tenantModules.metadata}, '{}'::jsonb) || ${metadataPatchJson}::jsonb`,
        updatedAt: /* @__PURE__ */ new Date()
      }).where(and7(
        eq7(tenantModules.tenantId, tenantId),
        eq7(tenantModules.moduleId, mod.id),
        sql5`(${tenantModules.metadata} -> 'freeWithAnyAccount') IS DISTINCT FROM 'true'::jsonb`
      ));
    }
    const ownerGrantInsert = database.insert(tenantUserModuleAccess).values({
      tenantId,
      userId: ownerUserId,
      moduleId: mod.id,
      accessLevel: "manager"
    });
    if (migrateLegacyGrant) {
      await ownerGrantInsert.onConflictDoUpdate({
        target: [tenantUserModuleAccess.tenantId, tenantUserModuleAccess.userId, tenantUserModuleAccess.moduleId],
        set: { accessLevel: "manager", updatedAt: /* @__PURE__ */ new Date() }
      });
    } else {
      await ownerGrantInsert.onConflictDoNothing({
        target: [tenantUserModuleAccess.tenantId, tenantUserModuleAccess.userId, tenantUserModuleAccess.moduleId]
      });
    }
  }
}
