async function backfillFreeAccountAppsForAllTenants() {
  const allTenants = await db.select({
    id: tenants.id,
    ownerUserId: tenants.ownerUserId,
    status: tenants.status
  }).from(tenants);
  let ensured = 0;
  let archivedSkipped = 0;
  for (const tenant2 of allTenants) {
    if (tenant2.status === "archived") {
      archivedSkipped += 1;
      continue;
    }
    await ensureFreeAccountApps(tenant2.id, tenant2.ownerUserId);
    ensured += 1;
  }
  console.log(
    `[backfill] Free-account apps: ${ensured} tenants ensured, ${archivedSkipped} archived tenants skipped`
  );
}
